   853  void Ip6::UpdateReassemblyList(void)
   854  {
   855      Message *next;
   856
   857      for (Message *message = mReassemblyList.GetHead(); message; message = next)
   858      {
   859          next = message->GetNext();
   860
   861          if (message->GetTimeout() > 0)
   862          {
   863              message->DecrementTimeout();
   864          }
   865          else
   866          {
   867              otLogNoteIp6("Reassembly timeout.");
   868              SendIcmpError(*message, IcmpHeader::kTypeTimeExceeded, IcmpHeader::kCodeFragmReasTimeEx);
   869
   870              mReassemblyList.Dequeue(*message);
   871              message->Free();
   872          }
   873      }
   874  }
