   876  otError Ip6::SendIcmpError(Message &aMessage, IcmpHeader::Type aIcmpType, IcmpHeader::Code aIcmpCode)
   877  {
   878      otError     error = OT_ERROR_NONE;
   879      Header      header;
   880      MessageInfo messageInfo;
   881
   882      VerifyOrExit(aMessage.Read(0, sizeof(header), &header) == sizeof(header), error = OT_ERROR_PARSE);
   883
   884      messageInfo.SetPeerAddr(header.GetSource());
   885      messageInfo.SetSockAddr(header.GetDestination());
   886      messageInfo.SetHopLimit(header.GetHopLimit());
   887      messageInfo.SetLinkInfo(NULL);
   888
   889      SuccessOrExit(error = mIcmp.SendError(aIcmpType, aIcmpCode, messageInfo, header));
   890
   891  exit:
   892      return error;
   893  }
