   926  otError Ip6::HandleExtensionHeaders(Message &    aMessage,
   927                                      Netif *      aNetif,
   928                                      MessageInfo &aMessageInfo,
   929                                      Header &     aHeader,
   930                                      uint8_t &    aNextHeader,
   931                                      bool         aForward,
   932                                      bool         aFromNcpHost,
   933                                      bool         aReceive)
   934  {
   935      otError         error = OT_ERROR_NONE;
   936      ExtensionHeader extHeader;
   937
   938      while (aReceive || aNextHeader == kProtoHopOpts)
   939      {
   940          VerifyOrExit(aMessage.Read(aMessage.GetOffset(), sizeof(extHeader), &extHeader) == sizeof(extHeader),
   941                       error = OT_ERROR_PARSE);
   942
   943          switch (aNextHeader)
   944          {
   945          case kProtoHopOpts:
   946              SuccessOrExit(error = HandleOptions(aMessage, aHeader, aForward));
   947              break;
   948
   949          case kProtoFragment:
   950              SuccessOrExit(error = HandleFragment(aMessage, aNetif, aMessageInfo, aFromNcpHost));
   951              break;
   952
   953          case kProtoDstOpts:
   954              SuccessOrExit(error = HandleOptions(aMessage, aHeader, aForward));
   955              break;
   956
   957          case kProtoIp6:
   958              ExitNow();
   959
   960          case kProtoRouting:
   961          case kProtoNone:
   962              ExitNow(error = OT_ERROR_DROP);
   963
   964          default:
   965              ExitNow();
   966          }
   967
   968          aNextHeader = static_cast<uint8_t>(extHeader.GetNextHeader());
   969      }
   970
   971  exit:
   972      return error;
   973  }
