   975  otError Ip6::HandlePayload(Message &aMessage, MessageInfo &aMessageInfo, uint8_t aIpProto)
   976  {
   977      otError error = OT_ERROR_NONE;
   978
   979      switch (aIpProto)
   980      {
   981      case kProtoUdp:
   982          error = mUdp.HandleMessage(aMessage, aMessageInfo);
   983          if (error == OT_ERROR_DROP)
   984          {
   985              otLogNoteIp6("Error UDP Checksum");
   986          }
   987          ExitNow();
   988
   989      case kProtoIcmp6:
   990          ExitNow(error = mIcmp.HandleMessage(aMessage, aMessageInfo));
   991      }
   992
   993  exit:
   994      return error;
   995  }
