   997  otError Ip6::ProcessReceiveCallback(const Message &    aMessage,
   998                                      const MessageInfo &aMessageInfo,
   999                                      uint8_t            aIpProto,
  1000                                      bool               aFromNcpHost)
  1001  {
  1002      otError  error       = OT_ERROR_NONE;
  1003      Message *messageCopy = NULL;
  1004
  1005      VerifyOrExit(!aFromNcpHost, error = OT_ERROR_NO_ROUTE);
  1006      VerifyOrExit(mReceiveIp6DatagramCallback != NULL, error = OT_ERROR_NO_ROUTE);
  1007
  1008      if (mIsReceiveIp6FilterEnabled)
  1009      {
  1010          // do not pass messages sent to an RLOC/ALOC, except Service Locator
  1011          VerifyOrExit(
  1012              (!aMessageInfo.GetSockAddr().IsRoutingLocator() && !aMessageInfo.GetSockAddr().IsAnycastRoutingLocator()) ||
  1013                  aMessageInfo.GetSockAddr().IsAnycastServiceLocator(),
  1014              error = OT_ERROR_NO_ROUTE);
  1015
  1016          switch (aIpProto)
  1017          {
  1018          case kProtoIcmp6:
  1019              if (mIcmp.ShouldHandleEchoRequest(aMessageInfo))
  1020              {
  1021                  IcmpHeader icmp;
  1022                  aMessage.Read(aMessage.GetOffset(), sizeof(icmp), &icmp);
  1023
  1024                  // do not pass ICMP Echo Request messages
  1025                  VerifyOrExit(icmp.GetType() != IcmpHeader::kTypeEchoRequest, error = OT_ERROR_DROP);
  1026              }
  1027
  1028              break;
  1029
  1030          case kProtoUdp:
  1031          {
  1032              UdpHeader udp;
  1033              aMessage.Read(aMessage.GetOffset(), sizeof(udp), &udp);
  1034
  1035              switch (udp.GetDestinationPort())
  1036              {
  1037              case Mle::kUdpPort:
  1038
  1039                  // do not pass MLE messages
  1040                  if (aMessageInfo.GetSockAddr().IsLinkLocal() || aMessageInfo.GetSockAddr().IsLinkLocalMulticast())
  1041                  {
  1042                      ExitNow(error = OT_ERROR_NO_ROUTE);
  1043                  }
  1044
  1045                  break;
  1046
  1047  #if OPENTHREAD_CONFIG_PLATFORM_UDP_ENABLE == 0
  1048              case kCoapUdpPort:
  1049
  1050                  // do not pass TMF messages
  1051                  if (Get<ThreadNetif>().IsTmfMessage(aMessageInfo))
  1052                  {
  1053                      ExitNow(error = OT_ERROR_NO_ROUTE);
  1054                  }
  1055
  1056                  break;
  1057  #endif // OPENTHREAD_CONFIG_PLATFORM_UDP_ENABLE
  1058
  1059              default:
  1060  #if OPENTHREAD_FTD
  1061                  if (udp.GetDestinationPort() == Get<MeshCoP::JoinerRouter>().GetJoinerUdpPort())
  1062                  {
  1063                      ExitNow(error = OT_ERROR_NO_ROUTE);
  1064                  }
  1065  #endif
  1066                  break;
  1067              }
  1068
  1069              break;
  1070          }
  1071
  1072          default:
  1073              break;
  1074          }
  1075      }
  1076
  1077      // make a copy of the datagram to pass to host
  1078      VerifyOrExit((messageCopy = aMessage.Clone()) != NULL, error = OT_ERROR_NO_BUFS);
  1079      RemoveMplOption(*messageCopy);
  1080      mReceiveIp6DatagramCallback(messageCopy, mReceiveIp6DatagramCallbackContext);
  1081
  1082  exit:
  1083
  1084      switch (error)
  1085      {
  1086      case OT_ERROR_NO_BUFS:
  1087          otLogWarnIp6("Failed to pass up message (len: %d) to host - out of message buffer.", aMessage.GetLength());
  1088          break;
  1089
  1090      case OT_ERROR_DROP:
  1091          otLogNoteIp6("Dropping message (len: %d) from local host since next hop is the host.", aMessage.GetLength());
  1092          break;
  1093
  1094      default:
  1095          break;
  1096      }
  1097
  1098      return error;
  1099  }
